import{_ as e,o as n,c as r,a0 as a}from"./chunks/framework.D7EjqxMK.js";const u=JSON.parse('{"title":"端到端 Agent 训练","description":"","frontmatter":{},"headers":[],"relativePath":"06-agent/05_前沿趋势/02_端到端 Agent 训练.md","filePath":"06-agent/05_前沿趋势/02_端到端 Agent 训练.md"}'),o={name:"06-agent/05_前沿趋势/02_端到端 Agent 训练.md"};function i(l,t,s,g,d,h){return n(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="端到端-agent-训练" tabindex="-1">端到端 Agent 训练 <a class="header-anchor" href="#端到端-agent-训练" aria-label="Permalink to &quot;端到端 Agent 训练&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块五 · 05_前沿趋势 · 第 2 节 <strong>难度</strong>：⭐⭐⭐ | <strong>前置知识</strong>：RLHF/RL</p></blockquote><hr><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>端到端 Agent 训练</strong>是指直接训练 LLM 成为 Agent，而非通过 Prompt Engineering。代表技术：RLHF → DPO → GRPO → 端到端 Agent 训练。</p><hr><h2 id="_2-技术演进" tabindex="-1">2. 技术演进 <a class="header-anchor" href="#_2-技术演进" aria-label="Permalink to &quot;2. 技术演进&quot;">​</a></h2><table tabindex="0"><thead><tr><th>技术</th><th>时间</th><th>核心</th></tr></thead><tbody><tr><td>RLHF</td><td>2022</td><td>人类偏好训练</td></tr><tr><td>DPO</td><td>2023</td><td>直接偏好优化</td></tr><tr><td>GRPO</td><td>2024</td><td>Group Relative Policy Optimization</td></tr><tr><td>AgentPRM</td><td>2025</td><td>Agent Process Reward Models</td></tr><tr><td>AgentFly</td><td>2025</td><td>Fine-tuning LLM Agents without Fine-tuning LLMs</td></tr></tbody></table><h3 id="process-reward-models-for-llm-agents-agentprm" tabindex="-1">Process Reward Models for LLM Agents (AgentPRM) <a class="header-anchor" href="#process-reward-models-for-llm-agents-agentprm" aria-label="Permalink to &quot;Process Reward Models for LLM Agents (AgentPRM)&quot;">​</a></h3><p>AgentPRM 是一种可扩展的 Agent 过程奖励模型。<a href="https://arxiv.org/html/2502.10325" target="_blank" rel="noreferrer">来源: AgentPRM (arXiv:2502.10325)</a></p><h3 id="agentfly-fine-tuning-llm-agents-without-fine-tuning-llms" tabindex="-1">AgentFly: Fine-tuning LLM Agents without Fine-tuning LLMs <a class="header-anchor" href="#agentfly-fine-tuning-llm-agents-without-fine-tuning-llms" aria-label="Permalink to &quot;AgentFly: Fine-tuning LLM Agents without Fine-tuning LLMs&quot;">​</a></h3><p>华为 Noah&#39;s Ark Lab 与 UCL 提出 AgentFly，在不微调 LLM 的前提下 fine-tuning Agent。<a href="https://arxiv.org/html/2508.16153v1" target="_blank" rel="noreferrer">来源: AgentFly (arXiv:2508.16153)</a></p><hr><h2 id="_3-参考资料" tabindex="-1">3. 参考资料 <a class="header-anchor" href="#_3-参考资料" aria-label="Permalink to &quot;3. 参考资料&quot;">​</a></h2><ul><li><a href="https://arxiv.org/html/2502.10325" target="_blank" rel="noreferrer">Process Reward Models for LLM Agents (AgentPRM)</a></li><li><a href="https://arxiv.org/html/2508.16153v1" target="_blank" rel="noreferrer">AgentFly: Fine-tuning LLM Agents without Fine-tuning LLMs</a></li><li><a href="https://cj.sina.com.cn/articles/view/7857201856/1d45362c001902swcu" target="_blank" rel="noreferrer">2025 Agent 综述 | 55页长文系统梳理</a></li></ul>',15)])])}const c=e(o,[["render",i]]);export{u as __pageData,c as default};
